animals = ["dog", "cat", "dog"]
class Animal:
    def make_sound(self):
        print("Animal sound")
class Dog(Animal):
    def make_sound(self):
        print("Bark!")
class Cat(Animal):
    def make_sound(self):
        print("Meow!")
def animal_sound(animal):
    animal.make_sound()
for kind in animals:
    if kind == "dog":
        animal_sound(Dog())
    elif kind == "cat":
        animal_sound(Cat())
    else:
        animal_sound(Animal())
